TEST(xpath_api_query_vector)
{
	std::vector<xpath_query> qv;

	for (int i = 0; i < 10; ++i)
	{
		char_t expr[2];
		expr[0] = char_t('0' + i);
		expr[1] = 0;

		qv.push_back(xpath_query(expr));
	}

	double result = 0;

	for (size_t i = 0; i < qv.size(); ++i)
		result += qv[i].evaluate_number(xml_node());

	CHECK(result == 45);
}
